package storage

import (
	"context"
	"encoding/json"
	"time"

	"github.com/lekramon/piratarr/internal/policies"
)

func policyJSON(value any) string { data, _ := json.Marshal(value); return string(data) }
func scanProfile(row interface{ Scan(...any) error }) (policies.Profile, error) {
	var p policies.Profile; var resolutions, formats, containers, audio string
	err := row.Scan(&p.ID,&p.Name,&p.Revision,&resolutions,&p.PreferredResolution,&formats,&containers,&audio,&p.CutoffScore,&p.AllowUpgrades,&p.UpdatedAt)
	if err != nil { return p, err }
	if err=json.Unmarshal([]byte(resolutions),&p.AcceptedResolutions); err!=nil{return p,err}; if err=json.Unmarshal([]byte(formats),&p.AcceptedFormats);err!=nil{return p,err}; if err=json.Unmarshal([]byte(containers),&p.AcceptedContainers);err!=nil{return p,err}; if err=json.Unmarshal([]byte(audio),&p.AudioPreferences);err!=nil{return p,err}; return p,nil
}
const profileColumns = "id,name,revision,accepted_resolutions,preferred_resolution,accepted_formats,accepted_containers,audio_preferences,cutoff_score,allow_upgrades,updated_at"
func (s *Store) ListAcquisitionProfiles(ctx context.Context) ([]policies.Profile,error) { rows,err:=s.read.QueryContext(ctx,"SELECT "+profileColumns+" FROM acquisition_profiles ORDER BY id"); if err!=nil{return nil,databaseError(err)}; defer rows.Close(); var out []policies.Profile; for rows.Next(){p,e:=scanProfile(rows);if e!=nil{return nil,e};out=append(out,p)};return out,rows.Err() }
func (s *Store) CreateAcquisitionProfile(ctx context.Context, in policies.ProfileInput) (policies.Profile,error) { if err:=policies.ValidateProfile(in);err!=nil{return policies.Profile{},err}; now:=time.Now().UTC().Format(time.RFC3339Nano); r,err:=s.write.ExecContext(ctx,"INSERT INTO acquisition_profiles(name,revision,accepted_resolutions,preferred_resolution,accepted_formats,accepted_containers,audio_preferences,cutoff_score,allow_upgrades,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",in.Name,1,policyJSON(in.AcceptedResolutions),in.PreferredResolution,policyJSON(in.AcceptedFormats),policyJSON(in.AcceptedContainers),policyJSON(in.AudioPreferences),in.CutoffScore,in.AllowUpgrades,now,now);if err!=nil{return policies.Profile{},databaseError(err)};id,_:=r.LastInsertId();return policies.Profile{ID:id,Name:in.Name,Revision:1,AcceptedResolutions:in.AcceptedResolutions,PreferredResolution:in.PreferredResolution,AcceptedFormats:in.AcceptedFormats,AcceptedContainers:in.AcceptedContainers,AudioPreferences:in.AudioPreferences,CutoffScore:in.CutoffScore,AllowUpgrades:in.AllowUpgrades,UpdatedAt:now},nil }
func (s *Store) UpdateAcquisitionProfile(ctx context.Context,id int64,revision int,in policies.ProfileInput)(policies.Profile,error){if err:=policies.ValidateProfile(in);err!=nil{return policies.Profile{},err};now:=time.Now().UTC().Format(time.RFC3339Nano);r,err:=s.write.ExecContext(ctx,"UPDATE acquisition_profiles SET name=?,revision=revision+1,accepted_resolutions=?,preferred_resolution=?,accepted_formats=?,accepted_containers=?,audio_preferences=?,cutoff_score=?,allow_upgrades=?,updated_at=? WHERE id=? AND revision=?",in.Name,policyJSON(in.AcceptedResolutions),in.PreferredResolution,policyJSON(in.AcceptedFormats),policyJSON(in.AcceptedContainers),policyJSON(in.AudioPreferences),in.CutoffScore,in.AllowUpgrades,now,id,revision);if err!=nil{return policies.Profile{},databaseError(err)};n,_:=r.RowsAffected();if n==0{return policies.Profile{},policies.ErrConflict};return policies.Profile{ID:id,Name:in.Name,Revision:revision+1,AcceptedResolutions:in.AcceptedResolutions,PreferredResolution:in.PreferredResolution,AcceptedFormats:in.AcceptedFormats,AcceptedContainers:in.AcceptedContainers,AudioPreferences:in.AudioPreferences,CutoffScore:in.CutoffScore,AllowUpgrades:in.AllowUpgrades,UpdatedAt:now},nil}
func (s *Store) AssignAcquisitionProfile(ctx context.Context,movieID,profileID int64) error { _,err:=s.write.ExecContext(ctx,"INSERT INTO movie_acquisition_profiles(movie_id,profile_id,assigned_at) VALUES(?,?,?) ON CONFLICT(movie_id) DO UPDATE SET profile_id=excluded.profile_id,assigned_at=excluded.assigned_at",movieID,profileID,time.Now().UTC().Format(time.RFC3339Nano));return databaseError(err) }
func (s *Store) ListQualityDefinitions(ctx context.Context)([]policies.QualityDefinition,error){rows,err:=s.read.QueryContext(ctx,"SELECT id,name,revision,resolution,source,min_size_per_minute,preferred_size_per_minute,max_size_per_minute FROM quality_definitions ORDER BY id");if err!=nil{return nil,databaseError(err)};defer rows.Close();var out []policies.QualityDefinition;for rows.Next(){var q policies.QualityDefinition;if err=rows.Scan(&q.ID,&q.Name,&q.Revision,&q.Resolution,&q.Source,&q.MinSizePerMinute,&q.PreferredSizePerMinute,&q.MaxSizePerMinute);err!=nil{return nil,err};out=append(out,q)};return out,rows.Err()}
func (s *Store) CreateQualityDefinition(ctx context.Context,in policies.QualityInput)(policies.QualityDefinition,error){if err:=policies.ValidateQuality(in);err!=nil{return policies.QualityDefinition{},err};r,err:=s.write.ExecContext(ctx,"INSERT INTO quality_definitions(name,revision,resolution,source,min_size_per_minute,preferred_size_per_minute,max_size_per_minute) VALUES(?,1,?,?,?,?,?)",in.Name,in.Resolution,in.Source,in.MinSizePerMinute,in.PreferredSizePerMinute,in.MaxSizePerMinute);if err!=nil{return policies.QualityDefinition{},databaseError(err)};id,_:=r.LastInsertId();return policies.QualityDefinition{ID:id,Name:in.Name,Revision:1,Resolution:in.Resolution,Source:in.Source,MinSizePerMinute:in.MinSizePerMinute,PreferredSizePerMinute:in.PreferredSizePerMinute,MaxSizePerMinute:in.MaxSizePerMinute},nil}
func (s *Store) ListCustomFormats(ctx context.Context)([]policies.CustomFormat,error){rows,err:=s.read.QueryContext(ctx,"SELECT id,name,revision,predicates,score,minimum_score FROM custom_formats ORDER BY id");if err!=nil{return nil,databaseError(err)};defer rows.Close();var out []policies.CustomFormat;for rows.Next(){var f policies.CustomFormat;var raw string;if err=rows.Scan(&f.ID,&f.Name,&f.Revision,&raw,&f.Score,&f.MinimumScore);err!=nil{return nil,err};if err=json.Unmarshal([]byte(raw),&f.Predicates);err!=nil{return nil,err};out=append(out,f)};return out,rows.Err()}
func (s *Store) CreateCustomFormat(ctx context.Context,in policies.CustomFormatInput)(policies.CustomFormat,error){if err:=policies.ValidateCustomFormat(in);err!=nil{return policies.CustomFormat{},err};r,err:=s.write.ExecContext(ctx,"INSERT INTO custom_formats(name,revision,predicates,score,minimum_score) VALUES(?,1,?,?,?)",in.Name,policyJSON(in.Predicates),in.Score,in.MinimumScore);if err!=nil{return policies.CustomFormat{},databaseError(err)};id,_:=r.LastInsertId();return policies.CustomFormat{ID:id,Name:in.Name,Revision:1,Predicates:in.Predicates,Score:in.Score,MinimumScore:in.MinimumScore},nil}
